186:         // Scenarios:
187:         //   c1,m1
188:         //   confirm c1, do nothing.
189:         //   c2,m1
190:         //   confirm c2, delete c1, don't delete m1
191:         //   c3,m2
192:         //   confirm c3, delete c2, delete m1
193: 
194:         // delete changelog-chk
195:         super.pruneCheckpoints(pruningChecker, false);
196:         deleteMaterialization(pruningChecker);
197:     }
