51:     /**
52:      * Enforces the correct completion order of the passed {@code CompletableFuture} instances in
53:      * accordance to the contract of {@link StopWithSavepointTerminationHandler}.
54:      *
55:      * @param completedSavepointFuture The {@code CompletableFuture} of the savepoint creation step.
56:      * @param terminatedExecutionStatesFuture The {@code CompletableFuture} of the termination step.
57:      * @param mainThreadExecutor The executor the {@code StopWithSavepointTerminationHandler}
58:      *     operations run on.
59:      * @return A {@code CompletableFuture} containing the path to the created savepoint.
60:      */
61:     public CompletableFuture<String> stopWithSavepoint(
62:             CompletableFuture<CompletedCheckpoint> completedSavepointFuture,
63:             CompletableFuture<Collection<ExecutionState>> terminatedExecutionStatesFuture,
64:             ComponentMainThreadExecutor mainThreadExecutor) {
65:         FutureUtils.assertNoException(
66:                 completedSavepointFuture
67:                         // the completedSavepointFuture could also be completed by
68:                         // CheckpointCanceller which doesn't run in the mainThreadExecutor
69:                         .handleAsync(
70:                                 (completedSavepoint, throwable) -> {
71:                                     stopWithSavepointTerminationHandler.handleSavepointCreation(
72:                                             completedSavepoint, throwable);
73:                                     return null;
74:                                 },
75:                                 mainThreadExecutor)
76:                         .thenRun(
77:                                 () ->
78:                                         FutureUtils.assertNoException(
79:                                                 // the execution termination has to run in a
80:                                                 // separate Runnable to disconnect it from any
81:                                                 // previous task failure handling
82:                                                 terminatedExecutionStatesFuture.thenAcceptAsync(
83:                                                         stopWithSavepointTerminationHandler
84:                                                                 ::handleExecutionsTermination,
85:                                                         mainThreadExecutor))));
86: 
