737:         Preconditions.checkArgument(
738:                 columnFamilyHandles.size() == registeredStateMetaInfoBases.size(),
739:                 "Lists are aligned by index and must be of the same size!");
740: 
741:         try (final Checkpoint checkpoint = Checkpoint.create(db)) {
742:             for (int i = 0; i < columnFamilyHandles.size(); i++) {
743:                 RegisteredStateMetaInfoBase.Key stateMetaInfoAsKey =
744:                         registeredStateMetaInfoBases.get(i).asMapKey();
