746:                 String uuid = UUID.randomUUID().toString();
747: 
748:                 String subPathStr =
749:                         optionsContainer.getRemoteBasePath() != null
750:                                 ? exportBasePath.getName() + "/" + uuid
751:                                 : exportBasePath.toString() + "/" + uuid;
752:                 ExportImportFilesMetaData exportedColumnFamilyMetaData =
753:                         checkpoint.exportColumnFamily(columnFamilyHandles.get(i), subPathStr);
754: 
755:                 FileStatus[] exportedSstFiles =
756:                         getFileSystem(exportBasePath).listStatus(new Path(exportBasePath, uuid));
