87:     public static KeyedStateBackend<Long> createKeyedStateBackend(
88:             StateBackendType backendType, File baseDir, TtlTimeProvider ttlTimeProvider)
89:             throws IOException {
90:         switch (backendType) {
91:             case HEAP:
92:                 rootDir = prepareDirectory(rootDirName, baseDir);
93:                 return createHeapKeyedStateBackend(rootDir, ttlTimeProvider);
94:             case ROCKSDB:
95:                 rootDir = prepareDirectory(rootDirName, baseDir);
96:                 return createRocksDBKeyedStateBackend(rootDir, ttlTimeProvider);
97:             case HEAP_CHANGELOG:
98:                 rootDir = prepareDirectory(rootDirName, baseDir);
99:                 return createChangelogKeyedStateBackend(
100:                         createHeapKeyedStateBackend(rootDir, ttlTimeProvider));
101:             case ROCKSDB_CHANGELOG:
102:                 rootDir = prepareDirectory(rootDirName, baseDir);
103:                 return createChangelogKeyedStateBackend(
104:                         createRocksDBKeyedStateBackend(rootDir, ttlTimeProvider));
105:             case BATCH_EXECUTION:
106:                 return createBatchExecutionStateBackend(ttlTimeProvider);
