51:     private GenericContainer<?> configureJobManagerContainer(Path tempDirectory) {
52:         // Configure JobManager
53:         final Configuration jobManagerConf = new Configuration();
54:         jobManagerConf.addAll(flinkContainersSettings.getFlinkConfig());
55:         // Build JobManager container
56:         final ImageFromDockerfile jobManagerImage;
57:         try {
58:             jobManagerImage =
59:                     new FlinkImageBuilder()
60:                             .setTempDirectory(tempDirectory)
61:                             .setConfiguration(jobManagerConf)
62:                             .setLogProperties(flinkContainersSettings.getLogProperties())
63:                             .setBaseImage(flinkContainersSettings.getBaseImage())
64:                             .asJobManager()
65:                             .build();
66:         } catch (ImageBuildException e) {
67:             throw new RuntimeException("Failed to build JobManager image", e);
68:         }
69:         return configureContainer(
70:                         new GenericContainer<>(jobManagerImage),
71:                         flinkContainersSettings.getJobManagerHostname(),
72:                         "JobManager")
73:                 .withExposedPorts(jobManagerConf.get(RestOptions.PORT));
74:     }
