115:     private GenericContainer<?> configureContainer(
116:             GenericContainer<?> container, String networkAlias, String logPrefix) {
117:         // Set dependent containers
118:         for (GenericContainer<?> dependentContainer : testcontainersSettings.getDependencies()) {
119:             dependentContainer.withNetwork(testcontainersSettings.getNetwork());
120:             container.dependsOn(dependentContainer);
121:         }
122:         // Setup network
123:         container.withNetwork(testcontainersSettings.getNetwork());
124:         container.withNetworkAliases(networkAlias);
125:         // Setup logger
126:         Logger logger = testcontainersSettings.getLogger();
127:         if (logger != null) {
128:             container.withLogConsumer(new Slf4jLogConsumer(logger).withPrefix(logPrefix));
129:         }
130:         // Add environment variables
131:         container.withEnv(testcontainersSettings.getEnvVars());
132:         container.withWorkingDirectory(flinkContainersSettings.getFlinkHome());
133:         return container;
