175:             file.setReadable(true, false);
176:             file.setWritable(true, false);
177:             file.setExecutable(true, false);
178:             container.withFileSystemBind(tempDirPath.toAbsolutePath().toString(), containerPath);
179:         } catch (IOException e) {
180:             throw new IllegalStateException("Failed to create temporary recovery directory", e);
181:         }
182:     }
