391:     private void testKeyGroupSnapshotRestore(
392:             int sourceParallelism, int targetParallelism, int maxParallelism) throws Exception {
393: 
394:         int aecBatchSize = 1;
395:         long aecBufferTimeout = 1;
396:         int aecMaxInFlightRecords = 1000;
397:         Random random = new Random();
398:         List<ValueStateDescriptor<Integer>> stateDescriptors = new ArrayList<>(maxParallelism);
399:         List<Integer> keyInKeyGroups = new ArrayList<>(maxParallelism);
400:         List<Integer> expectedValue = new ArrayList<>(maxParallelism);
401:         for (int i = 0; i < maxParallelism; ++i) {
402:             // all states have different name to mock that all the parallelisms of one operator have
403:             // different states.
404:             stateDescriptors.add(
405:                     new ValueStateDescriptor<>("state" + i, BasicTypeInfo.INT_TYPE_INFO));
406:         }
407: 
408:         CheckpointStreamFactory streamFactory = createStreamFactory();
409:         SharedStateRegistry sharedStateRegistry = new SharedStateRegistryImpl();
410:         AsyncExecutionController<Integer> aec;
411: 
412:         TestAsyncFrameworkExceptionHandler testExceptionHandler =
413:                 new TestAsyncFrameworkExceptionHandler();
414: 
415:         List<KeyedStateHandle> snapshots = new ArrayList<>(sourceParallelism);
416:         for (int i = 0; i < sourceParallelism; ++i) {
417:             KeyGroupRange range =
418:                     KeyGroupRange.of(
419:                             maxParallelism * i / sourceParallelism,
420:                             maxParallelism * (i + 1) / sourceParallelism - 1);
421:             AsyncKeyedStateBackend<Integer> backend =
422:                     createAsyncKeyedBackend(
423:                             i, sourceParallelism, IntSerializer.INSTANCE, range, env);
424:             aec =
425:                     new AsyncExecutionController<>(
426:                             new SyncMailboxExecutor(),
427:                             testExceptionHandler,
428:                             backend.createStateExecutor(),
429:                             new DeclarationManager(),
430:                             maxParallelism,
431:                             aecBatchSize,
432:                             aecBufferTimeout,
433:                             aecMaxInFlightRecords,
434:                             null,
435:                             null);
436:             backend.setup(aec);
437: 
438:             try {
439:                 for (int j = range.getStartKeyGroup(); j <= range.getEndKeyGroup(); ++j) {
440:                     ValueState<Integer> state =
441:                             backend.getOrCreateKeyedState(
442:                                     VoidNamespace.INSTANCE,
443:                                     VoidNamespaceSerializer.INSTANCE,
444:                                     stateDescriptors.get(j));
445:                     int keyInKeyGroup =
446:                             getKeyInKeyGroup(random, maxParallelism, KeyGroupRange.of(j, j));
447:                     RecordContext recordContext = aec.buildContext(keyInKeyGroup, keyInKeyGroup);
448:                     recordContext.retain();
449:                     aec.setCurrentContext(recordContext);
450:                     keyInKeyGroups.add(keyInKeyGroup);
451:                     state.update(keyInKeyGroup);
452:                     expectedValue.add(keyInKeyGroup);
453:                     recordContext.release();
454:                 }
455: 
456:                 // snapshot
457:                 snapshots.add(
458:                         runSnapshot(
459:                                 backend.snapshot(
460:                                         0,
461:                                         0,
462:                                         streamFactory,
463:                                         CheckpointOptions.forCheckpointWithDefaultLocation()),
464:                                 sharedStateRegistry));
465:             } finally {
466:                 IOUtils.closeQuietly(backend);
467:                 backend.dispose();
468:             }
469:         }
470: 
471:         // redistribute the stateHandle
472:         List<KeyGroupRange> keyGroupRangesRestore = new ArrayList<>();
473:         for (int i = 0; i < targetParallelism; ++i) {
474:             keyGroupRangesRestore.add(
475:                     KeyGroupRangeAssignment.computeKeyGroupRangeForOperatorIndex(
476:                             maxParallelism, targetParallelism, i));
477:         }
478:         List<List<KeyedStateHandle>> keyGroupStatesAfterDistribute =
479:                 new ArrayList<>(targetParallelism);
480:         for (int i = 0; i < targetParallelism; ++i) {
481:             List<KeyedStateHandle> keyedStateHandles = new ArrayList<>();
482:             StateAssignmentOperation.extractIntersectingState(
483:                     snapshots, keyGroupRangesRestore.get(i), keyedStateHandles);
484:             keyGroupStatesAfterDistribute.add(keyedStateHandles);
485:         }
486:         // restore and verify
487:         for (int i = 0; i < targetParallelism; ++i) {
488:             AsyncKeyedStateBackend<Integer> backend =
489:                     restoreAsyncKeyedBackend(
490:                             i,
491:                             targetParallelism,
492:                             IntSerializer.INSTANCE,
493:                             keyGroupRangesRestore.get(i),
494:                             keyGroupStatesAfterDistribute.get(i),
495:                             env);
496:             aec =
497:                     new AsyncExecutionController<>(
498:                             new SyncMailboxExecutor(),
499:                             testExceptionHandler,
500:                             backend.createStateExecutor(),
501:                             new DeclarationManager(),
502:                             maxParallelism,
503:                             aecBatchSize,
504:                             aecBufferTimeout,
505:                             aecMaxInFlightRecords,
506:                             null,
507:                             null);
508:             backend.setup(aec);
509: 
510:             try {
511:                 KeyGroupRange range = keyGroupRangesRestore.get(i);
512:                 for (int j = range.getStartKeyGroup(); j <= range.getEndKeyGroup(); ++j) {
513:                     ValueState<Integer> state =
514:                             backend.getOrCreateKeyedState(
515:                                     VoidNamespace.INSTANCE,
516:                                     VoidNamespaceSerializer.INSTANCE,
517:                                     stateDescriptors.get(j));
518:                     RecordContext recordContext =
519:                             aec.buildContext(keyInKeyGroups.get(j), keyInKeyGroups.get(j));
520:                     recordContext.retain();
521:                     aec.setCurrentContext(recordContext);
522:                     assertThat(state.value()).isEqualTo(expectedValue.get(j));
523:                     recordContext.release();
524:                 }
525:             } finally {
526:                 IOUtils.closeQuietly(backend);
527:                 backend.dispose();
528:             }
529:         }
530:     }
