542:     void testKeyGroupedInternalPriorityQueue(boolean addAll) throws Exception {
543:         String fieldName = "key-grouped-priority-queue";
544:         AsyncKeyedStateBackend<Integer> backend =
545:                 createAsyncKeyedBackend(
546:                         0, 1, IntSerializer.INSTANCE, new KeyGroupRange(0, 127), env);
547:         try {
548:             KeyGroupedInternalPriorityQueue<TestType> priorityQueue =
549:                     backend.create(fieldName, new TestType.V1TestTypeSerializer());
550: 
551:             TestType elementA42 = new TestType("a", 42);
552:             TestType elementA44 = new TestType("a", 44);
553:             TestType elementB1 = new TestType("b", 1);
554:             TestType elementB3 = new TestType("b", 3);
555: 
556:             TestType[] elements = {
557:                 elementA44, elementB1, elementB1, elementB3, elementA42,
558:             };
559: 
560:             if (addAll) {
561:                 priorityQueue.addAll(asList(elements));
562:             } else {
563:                 assertThat(priorityQueue.add(elements[0])).isTrue();
564:                 assertThat(priorityQueue.add(elements[1])).isTrue();
565:                 assertThat(priorityQueue.add(elements[2])).isFalse();
566:                 assertThat(priorityQueue.add(elements[3])).isFalse();
567:                 assertThat(priorityQueue.add(elements[4])).isFalse();
568:             }
569:             assertThat(priorityQueue.isEmpty()).isFalse();
570:             assertThat(priorityQueue.getSubsetForKeyGroup(81))
571:                     .containsExactlyInAnyOrder(elementA42, elementA44);
572:             assertThat(priorityQueue.getSubsetForKeyGroup(22))
573:                     .containsExactlyInAnyOrder(elementB1, elementB3);
574: 
575:             assertThat(priorityQueue.peek()).isEqualTo(elementB1);
576:             assertThat(priorityQueue.poll()).isEqualTo(elementB1);
577:             assertThat(priorityQueue.peek()).isEqualTo(elementB3);
578: 
579:             List<TestType> actualList = new ArrayList<>();
580:             try (CloseableIterator<TestType> iterator = priorityQueue.iterator()) {
581:                 iterator.forEachRemaining(actualList::add);
582:             }
583: 
584:             assertThat(actualList).containsExactlyInAnyOrder(elementB3, elementA42, elementA44);
585: 
586:             assertThat(priorityQueue.size()).isEqualTo(3);
587: 
588:             assertThat(priorityQueue.remove(elementB1)).isFalse();
589:             assertThat(priorityQueue.remove(elementB3)).isTrue();
590:             assertThat(priorityQueue.peek()).isEqualTo(elementA42);
591:         } finally {
592:             IOUtils.closeQuietly(backend);
593:             backend.dispose();
594:         }
595:     }
