659:     /** Returns an Integer key in specified keyGroupRange. */
660:     private int getKeyInKeyGroup(Random random, int maxParallelism, KeyGroupRange keyGroupRange) {
661:         int keyInKG = random.nextInt();
662:         int kg = KeyGroupRangeAssignment.assignToKeyGroup(keyInKG, maxParallelism);
663:         while (!keyGroupRange.contains(kg)) {
664:             keyInKG = random.nextInt();
665:             kg = KeyGroupRangeAssignment.assignToKeyGroup(keyInKG, maxParallelism);
666:         }
667:         return keyInKG;
668:     }
