670:     private static KeyedStateHandle runSnapshot(
671:             RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshotRunnableFuture,
672:             SharedStateRegistry sharedStateRegistry)
673:             throws Exception {
674: 
675:         if (!snapshotRunnableFuture.isDone()) {
676:             snapshotRunnableFuture.run();
677:         }
678: 
679:         SnapshotResult<KeyedStateHandle> snapshotResult = snapshotRunnableFuture.get();
680:         KeyedStateHandle jobManagerOwnedSnapshot = snapshotResult.getJobManagerOwnedSnapshot();
681:         if (jobManagerOwnedSnapshot != null) {
682:             jobManagerOwnedSnapshot.registerSharedStates(sharedStateRegistry, 0L);
683:         }
684:         return jobManagerOwnedSnapshot;
685:     }
