197:     /** Trigger the object config serialization and return the completable future. */
198:     public CompletableFuture<StreamConfig> triggerSerializationAndReturnFuture(
199:             Executor ioExecutor) {
200:         FutureUtils.combineAll(chainedTaskFutures.values())
201:                 .thenAcceptAsync(
202:                         chainedConfigs -> {
203:                             try {
204:                                 // Serialize all the objects to config.
205:                                 serializeAllConfigs();
206:                                 InstantiationUtil.writeObjectToConfig(
207:                                         chainedConfigs.stream()
208:                                                 .collect(
209:                                                         Collectors.toMap(
210:                                                                 StreamConfig::getVertexID,
211:                                                                 Function.identity())),
212:                                         this.config,
213:                                         CHAINED_TASK_CONFIG);
214:                                 serializationFuture.complete(this);
215:                             } catch (Throwable throwable) {
216:                                 serializationFuture.completeExceptionally(throwable);
217:                             }
218:                         },
219:                         ioExecutor);
220:         return serializationFuture;
221:     }
