381:     private void triggerCheckpointWaitForFinish(
382:             StreamTaskMailboxTestHarness<Integer> testHarness,
383:             long checkpointId,
384:             CheckpointOptions checkpointOptions)
385:             throws Exception {
386:         // Trigger a checkpoint.
387:         testHarness.taskStateManager.getWaitForReportLatch().reset();
388:         CheckpointMetaData checkpointMetaData = new CheckpointMetaData(checkpointId, checkpointId);
389:         Future<Boolean> checkpointFuture =
390:                 testHarness
391:                         .getStreamTask()
392:                         .triggerCheckpointAsync(checkpointMetaData, checkpointOptions);
393: 
394:         // Wait until the checkpoint finishes.
395:         // We have to mark the source reader as available here, otherwise the runMailboxStep() call
396:         // after
397:         // checkpoint is completed will block.
398:         getSourceReaderFromTask(testHarness).markAvailable();
399:         processUntil(testHarness, checkpointFuture::isDone);
400:         Future<Void> checkpointNotified =
401:                 testHarness.getStreamTask().notifyCheckpointCompleteAsync(checkpointId);
402:         processUntil(testHarness, checkpointNotified::isDone);
403:         testHarness.taskStateManager.getWaitForReportLatch().await();
404:     }
