426:     /**
427:      * A simple {@link FilenameFilter} that only accepts files if their name contains every string
428:      * in the array passed to the constructor.
429:      */
430:     public static class ContainsName implements FilenameFilter {
431:         private String[] names;
432:         private String excludeInPath = null;
433: 
434:         /** @param names which have to be included in the filename. */
435:         public ContainsName(String[] names) {
436:             this.names = names;
437:         }
438: 
439:         public ContainsName(String[] names, String excludeInPath) {
440:             this.names = names;
441:             this.excludeInPath = excludeInPath;
442:         }
443: 
444:         @Override
445:         public boolean accept(File dir, String name) {
446:             if (excludeInPath == null) {
447:                 for (String n : names) {
448:                     if (!name.contains(n)) {
449:                         return false;
450:                     }
451:                 }
452:                 return true;
453:             } else {
454:                 for (String n : names) {
455:                     if (!name.contains(n)) {
456:                         return false;
457:                     }
458:                 }
459:                 return !dir.toString().contains(excludeInPath);
460:             }
461:         }
462:     }
