915: 
916:         outContent = new ByteArrayOutputStream();
917:         errContent = new ByteArrayOutputStream();
918:         PipedOutputStream out = new PipedOutputStream();
919:         PipedInputStream in = new PipedInputStream(out);
920:         PrintStream stdinPrintStream = new PrintStream(out);
921: 
922:         System.setOut(new PrintStream(outContent));
923:         System.setErr(new PrintStream(errContent));
924:         System.setIn(in);
925: 
926:         final int startTimeoutSeconds = 60;
927: 
928:         Runner runner =
929:                 new Runner(
930:                         args,
931:                         flinkConfiguration,
932:                         CliFrontend.getConfigurationDirectoryFromEnv(),
933:                         type,
934:                         0,
935:                         stdinPrintStream);
936:         runner.setName("Frontend (CLI/YARN Client) runner thread (startWithArgs()).");
937:         runner.start();
938: 
939:         for (int second = 0; second < startTimeoutSeconds; second++) {
940:             sleep(1000);
941:             // check output for correct TaskManager startup.
942:             if (outContent.toString().contains(startedAfterString)
943:                     || errContent.toString().contains(startedAfterString)) {
944:                 LOG.info("Found expected output in redirected streams");
945:                 return runner;
946:             }
947:             // check if thread died
948:             if (!runner.isAlive()) {
949:                 resetStreamsAndSendOutput();
950:                 if (runner.getRunnerError() != null) {
951:                     throw new RuntimeException(
952:                             "Runner failed with exception.", runner.getRunnerError());
953:                 }
954:                 fail("Runner thread died before the test was finished.");
955:             }
956:         }
957: 
958:         resetStreamsAndSendOutput();
959:         fail(
960:                 "During the timeout period of "
961:                         + startTimeoutSeconds
962:                         + " seconds the "
963:                         + "expected string did not show up");
964:         return null;
965:     }
