983:     /**
984:      * The test has been passed once the "terminateAfterString" has been seen.
985:      *
986:      * @param args Command line arguments for the runner
987:      * @param terminateAfterString the runner is searching the stdout and stderr for this string. as
988:      *     soon as it appears, the test has passed
989:      * @param failOnPatterns The runner is searching stdout and stderr for the pattern (regexp)
990:      *     specified here. If one appears, the test has failed
991:      * @param type Set the type of the runner
992:      * @param expectedReturnValue Expected return code from the runner.
993:      * @param logMessageSupplier Supplier for log messages
994:      */
995:     protected void runWithArgs(
996:             String[] args,
997:             String terminateAfterString,
998:             String[] failOnPatterns,
999:             RunTypes type,
1000:             int expectedReturnValue,
1001:             Supplier<Collection<String>> logMessageSupplier)
1002:             throws IOException {
1003:         LOG.info("Running with args {}", Arrays.toString(args));
1004: 
1005:         outContent = new ByteArrayOutputStream();
1006:         errContent = new ByteArrayOutputStream();
1007:         PipedOutputStream out = new PipedOutputStream();
1008:         PipedInputStream in = new PipedInputStream(out);
1009:         PrintStream stdinPrintStream = new PrintStream(out);
1010:         System.setOut(new PrintStream(outContent));
1011:         System.setErr(new PrintStream(errContent));
1012:         System.setIn(in);
1013: 
1014:         // we wait for at most three minutes
1015:         final int startTimeoutSeconds = 180;
1016:         final long deadline = System.currentTimeMillis() + (startTimeoutSeconds * 1000);
1017: 
1018:         Runner runner =
1019:                 new Runner(
1020:                         args,
1021:                         flinkConfiguration,
1022:                         CliFrontend.getConfigurationDirectoryFromEnv(),
1023:                         type,
1024:                         expectedReturnValue,
1025:                         stdinPrintStream);
1026:         runner.start();
1027: 
1028:         boolean expectedStringSeen = false;
1029:         boolean testPassedFromLog4j = false;
1030:         long shutdownTimeout = 30000L;
1031:         do {
1032:             sleep(1000);
1033:             String outContentString = outContent.toString();
1034:             String errContentString = errContent.toString();
1035:             if (failOnPatterns != null) {
1036:                 for (String failOnString : failOnPatterns) {
1037:                     Pattern pattern = Pattern.compile(failOnString);
1038:                     if (pattern.matcher(outContentString).find()
1039:                             || pattern.matcher(errContentString).find()) {
1040:                         LOG.warn(
1041:                                 "Failing test. Output contained illegal string '"
1042:                                         + failOnString
1043:                                         + "'");
1044:                         resetStreamsAndSendOutput();
1045:                         // stopping runner.
1046:                         runner.sendStop();
1047:                         // wait for the thread to stop
1048:                         try {
1049:                             runner.join(shutdownTimeout);
1050:                         } catch (InterruptedException e) {
1051:                             LOG.warn("Interrupted while stopping runner", e);
1052:                         }
1053:                         fail("Output contained illegal string '" + failOnString + "'");
