219:     private static Map<ExecutionVertexID, SlotExecutionVertexAssignment>
220:             allocateLogicalSlotsFromSharedSlots(
221:                     Map<ExecutionSlotSharingGroup, SharedSlot> slots,
222:                     Map<ExecutionSlotSharingGroup, List<ExecutionVertexID>> executionsByGroup) {
223: 
224:         Map<ExecutionVertexID, SlotExecutionVertexAssignment> assignments = new HashMap<>();
225: 
226:         for (Map.Entry<ExecutionSlotSharingGroup, List<ExecutionVertexID>> entry :
227:                 executionsByGroup.entrySet()) {
228:             ExecutionSlotSharingGroup group = entry.getKey();
229:             List<ExecutionVertexID> executionIds = entry.getValue();
230: 
231:             for (ExecutionVertexID executionId : executionIds) {
232:                 CompletableFuture<LogicalSlot> logicalSlotFuture =
233:                         slots.get(group).allocateLogicalSlot(executionId);
234:                 SlotExecutionVertexAssignment assignment =
235:                         new SlotExecutionVertexAssignment(executionId, logicalSlotFuture);
236:                 assignments.put(executionId, assignment);
