316:     private ResourceProfile getPhysicalSlotResourceProfile(
317:             ExecutionSlotSharingGroup executionSlotSharingGroup) {
318:         if (!executionSlotSharingGroup.getResourceProfile().equals(ResourceProfile.UNKNOWN)) {
319:             return executionSlotSharingGroup.getResourceProfile();
320:         } else {
321:             return executionSlotSharingGroup.getExecutionVertexIds().stream()
322:                     .reduce(
323:                             ResourceProfile.ZERO,
324:                             (r, e) -> r.merge(resourceProfileRetriever.apply(e)),
325:                             ResourceProfile::merge);
326:         }
327:     }
