135:     /**
136:      * Creates logical {@link SlotExecutionVertexAssignment}s from physical shared slots.
137:      *
138:      * <p>The allocation has the following steps:
139:      *
140:      * <ol>
141:      *   <li>Map the executions to {@link ExecutionSlotSharingGroup}s using {@link
142:      *       SlotSharingStrategy}
143:      *   <li>Check which {@link ExecutionSlotSharingGroup}s already have shared slot
144:      *   <li>For all involved {@link ExecutionSlotSharingGroup}s which do not have a shared slot
145:      *       yet:
146:      *   <li>Create a {@link SlotProfile} future using {@link SharedSlotProfileRetriever} and then
147:      *   <li>Allocate a physical slot from the {@link PhysicalSlotProvider}
148:      *   <li>Create a shared slot based on the returned physical slot futures
149:      *   <li>Allocate logical slot futures for the executions from all corresponding shared slots.
150:      *   <li>If a physical slot request fails, associated logical slot requests are canceled within
151:      *       the shared slot
152:      *   <li>Generate {@link SlotExecutionVertexAssignment}s based on the logical slot futures and
153:      *       returns the results.
154:      * </ol>
155:      *
156:      * @param executionVertexIds Execution vertices to allocate slots for
157:      */
158:     private List<SlotExecutionVertexAssignment> allocateSlotsForVertices(
159:             List<ExecutionVertexID> executionVertexIds) {
160: 
161:         SharedSlotProfileRetriever sharedSlotProfileRetriever =
162:                 sharedSlotProfileRetrieverFactory.createFromBulk(new HashSet<>(executionVertexIds));
163:         Map<ExecutionSlotSharingGroup, List<ExecutionVertexID>> executionsByGroup =
164:                 executionVertexIds.stream()
165:                         .collect(
166:                                 Collectors.groupingBy(
167:                                         slotSharingStrategy::getExecutionSlotSharingGroup));
168: 
169:         Map<ExecutionSlotSharingGroup, SharedSlot> slots = new HashMap<>(executionsByGroup.size());
170:         Set<ExecutionSlotSharingGroup> groupsToAssign = new HashSet<>(executionsByGroup.keySet());
171: 
172:         Map<ExecutionSlotSharingGroup, SharedSlot> assignedSlots =
173:                 tryAssignExistingSharedSlots(groupsToAssign);
174:         slots.putAll(assignedSlots);
175:         groupsToAssign.removeAll(assignedSlots.keySet());
176: 
177:         if (!groupsToAssign.isEmpty()) {
178:             Map<ExecutionSlotSharingGroup, SharedSlot> allocatedSlots =
179:                     allocateSharedSlots(groupsToAssign, sharedSlotProfileRetriever);
180:             slots.putAll(allocatedSlots);
181:             groupsToAssign.removeAll(allocatedSlots.keySet());
182:             Preconditions.checkState(groupsToAssign.isEmpty());
183:         }
184: 
185:         Map<ExecutionVertexID, SlotExecutionVertexAssignment> assignments =
186:                 allocateLogicalSlotsFromSharedSlots(slots, executionsByGroup);
187: 
188:         // we need to pass the slots map to the createBulk method instead of using the allocator's
189:         // 'sharedSlots'
190:         // because if any physical slots have already failed, their shared slots have been removed
191:         // from the allocator's 'sharedSlots' by failed logical slots.
192:         SharingPhysicalSlotRequestBulk bulk = createBulk(slots, executionsByGroup);
193:         bulkChecker.schedulePendingRequestBulkTimeoutCheck(bulk, submissionResourceWaitTimeout);
194: 
195:         return executionVertexIds.stream().map(assignments::get).collect(Collectors.toList());
196:     }
