203:     private void cancelLogicalSlotRequest(ExecutionVertexID executionVertexId, Throwable cause) {
204:         ExecutionSlotSharingGroup executionSlotSharingGroup =
205:                 slotSharingStrategy.getExecutionSlotSharingGroup(executionVertexId);
206:         checkNotNull(
207:                 executionSlotSharingGroup,
208:                 "There is no ExecutionSlotSharingGroup for ExecutionVertexID " + executionVertexId);
209:         SharedSlot slot = sharedSlots.get(executionSlotSharingGroup);
210:         if (slot != null) {
211:             slot.cancelLogicalSlotRequest(executionVertexId, cause);
212:         } else {
213:             LOG.debug(
214:                     "There is no SharedSlot for ExecutionSlotSharingGroup of ExecutionVertexID {}",
215:                     executionVertexId);
216:         }
217:     }
