365:     private static class SlotExecutionVertexAssignment {
366: 
367:         private final ExecutionVertexID executionVertexId;
368: 
369:         private final CompletableFuture<LogicalSlot> logicalSlotFuture;
370: 
371:         SlotExecutionVertexAssignment(
372:                 ExecutionVertexID executionVertexId,
373:                 CompletableFuture<LogicalSlot> logicalSlotFuture) {
374:             this.executionVertexId = checkNotNull(executionVertexId);
375:             this.logicalSlotFuture = checkNotNull(logicalSlotFuture);
376:         }
377: 
378:         ExecutionVertexID getExecutionVertexId() {
379:             return executionVertexId;
380:         }
381: 
382:         CompletableFuture<LogicalSlot> getLogicalSlotFuture() {
383:             return logicalSlotFuture;
384:         }
